-- 2026-10-w3 G2(夜の急ぎ配置中): 動画レビューの指摘で C70・C71 のイラストを作り直すための修正
-- C70: 植物を出さないため問題文・出題要旨の「芝生」→「庭」、情景を土の地面へ / C71: 光源・縁取りの光をなくした情景へ
-- 適用先: ローカル MySQL / Aurora(content_key で解決)

-- C70
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.question_text = '春先の朝、庭に、炭が5個、ニンジンが1本、マフラーが1本落ちていた。きのうまでは、庭に何も落ちていなかった。なぜ?', q.content_fields = CAST('{"hook": "春の朝のミステリーだ", "hint": "季節をさかのぼってみろ!", "question": "春先の朝、庭に、炭が5個、ニンジンが1本、マフラーが1本落ちていた。きのうまでは、庭に何も落ちていなかった。なぜ?", "answer": "雪だるまがとけたから", "explanation": "だれかが落としたと考えると行き詰まる。冬に作った雪だるまの目とボタンの炭、鼻のニンジン、首のマフラーが、雪がとけて残ったのだ。", "coach_comment": "季節ごと推理したな!", "tags": ["水平思考", "夜の一問", "推理"], "summary": "春先の庭に炭5個・ニンジン・マフラーが落ちていた理由を問う水平思考の定番。答えは雪だるまがとけた。落とし物ではなく、とけて残ったもの。", "illustration_scene": "夜、窓の明かりに照らされた家の庭。庭は乾いた茶色い土の地面と家の壁だけ。地面の上に、ピンポン玉ほどの大きさの黒い炭のかたまりが5個、手のひらほどの長さのニンジンが1本、赤い毛糸のマフラーが1本、ばらばらに落ちている。地面の上に大きな「?」。人物・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'night-064';

-- C71
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "停電の夜の不思議だ", "hint": "読み方は1つじゃないぞ!", "question": "新月の夜に停電して、家じゅう真っ暗。明かりは1つもないのに、男は分厚い本を最後まで読み続けた。なぜ?", "answer": "目の見えない人で、点字の本を読んでいたから", "explanation": "明かりの代わりを探すと行き詰まる。男は目の見えない人で、指先で点字を読んでいた。暗くても読書には何の問題もなかったのだ。", "coach_comment": "前提をひっくり返したな!", "tags": ["水平思考", "夜の一問", "ひっかけ"], "summary": "新月の夜の停電で真っ暗な家で、明かりもなく分厚い本を最後まで読んだ理由を問う水平思考の定番。答えは目の見えない人が点字の本を読んでいた。", "illustration_scene": "夜、停電で真っ暗な部屋。部屋全体がほぼ真っ黒で、ソファに座った男の後ろ姿と膝の上に開いた分厚い本が、黒に近い濃い紺色のシルエットでかろうじて分かるだけ。本のページも暗く無地。窓の外は真っ黒な夜空。光源・照り返し・輪郭の縁取りの光は一切ない。男の頭上に大きな「?」。顔・「?」以外の文字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'night-065';
